<?php

namespace Mautic\CoreBundle\Twig\Helper;

final class MautibotHelper
{
    public const OPEN_MOUTH      = 'openMouth';

    public const SMILE           = 'smile';

    public const WAVE            = 'wave';

    public const WELCOME         = 'welcome';

    public const SVG_WELCOME     = 'data:image/svg+xml;base64,';

    public const HAPPY           = 'happy';

    public const SVG_HAPPY       = 'data:image/svg+xml;base64,';

    public const INFORMATION     = 'information';

    public const SVG_INFORMATION = 'data:image/svg+xml;base64,';

    public const WARNING         = 'warning';

    public const SVG_WARNING     = 'data:image/svg+xml;base64,';

    public const DANGER          = 'danger';

    public const SVG_DANGER      = 'data:image/svg+xml;base64,';

    public const ERROR           = 'error';

    public const SVG_ERROR       = 'data:image/svg+xml;base64,';

    /**
     * @param string $image openMouth | smile | wave
     */
    public function getImage($image): string
    {
        return self::get($image);
    }

    /**
     * Static alternative to retrieve image.
     *
     * @param string $image openMouth | smile | wave | welcome | happy | information | warning | danger | error
     */
    public static function get($image): string
    {
        return match ($image) {
            self::OPEN_MOUTH  => self::SVG_WARNING,
            self::SMILE       => self::SVG_HAPPY,
            self::WAVE        => self::SVG_WELCOME,
            self::WELCOME     => self::SVG_WELCOME,
            self::HAPPY       => self::SVG_HAPPY,
            self::INFORMATION => self::SVG_INFORMATION,
            self::WARNING     => self::SVG_WARNING,
            self::DANGER      => self::SVG_DANGER,
            self::ERROR       => self::SVG_ERROR,
            default           => '',
        };
    }

    public function getName(): string
    {
        return 'mautibot';
    }
}
